import { readdirSync, readFileSync } from "fs";
import { join } from "path";

const dir = "wiki/npcs";
const rows: any[] = [];
for (const f of readdirSync(dir)) {
  if (!f.endsWith(".md")) continue;
  const t = readFileSync(join(dir, f), "utf8");
  const name = (t.match(/^# (.+)$/m) || [])[1] || f;
  const cl = (t.match(/\*\*Combat Level\*\* \| ([^\n|]+)/) || [])[1]?.trim() ?? "";
  const hp = (t.match(/\*\*Hitpoints\*\* \| ([^\n|]+)/) || [])[1]?.trim() ?? "";
  const def = (t.match(/\*\*Stab Defence\*\* \| ([^\n|]+)/) || [])[1]?.trim() ?? "";
  const slash = (t.match(/\*\*Slash Defence\*\* \| ([^\n|]+)/) || [])[1]?.trim() ?? "";
  const crush = (t.match(/\*\*Crush Defence\*\* \| ([^\n|]+)/) || [])[1]?.trim() ?? "";
  const atk = (t.match(/\*\*Attack Bonus\*\* \| ([^\n|]+)/) || [])[1]?.trim() ?? "";
  const str = (t.match(/\*\*Strength Bonus\*\* \| ([^\n|]+)/) || [])[1]?.trim() ?? "";
  const aggr = (t.match(/\*\*Aggressive\*\* \| ([^\n|]+)/) || [])[1]?.trim() ?? "";
  const locs = (t.split("## Locations")[1] || "").split("##")[0];
  const lum = /Lumbridge/i.test(locs);
  const clNum = cl.match(/\d+/g)?.map(Number) ?? [];
  const hpNum = hp.match(/\d+/g)?.map(Number) ?? [];
  const defNum = (s: string) => { const m = s.match(/-?\d+/); return m ? Number(m[0]) : NaN; };
  const minDef = Math.min(defNum(def), defNum(slash), defNum(crush));
  rows.push({
    name, cl: clNum.length ? Math.max(...clNum) : null, clMin: clNum.length?Math.min(...clNum):null,
    hpMax: hpNum.length ? Math.max(...hpNum) : null, minDef, atk: defNum(atk), str: defNum(str),
    aggr, lum, file: f,
  });
}
rows.sort((a, b) => (b.cl ?? -1) - (a.cl ?? -1));
console.log("=== Top by max combat level with def <= -10 and HP>=10 (reachable-ish) ===");
for (const r of rows) {
  if ((r.cl ?? 0) >= 15 && r.minDef <= -10 && (r.hpMax ?? 0) >= 10) {
    console.log(`${r.name.padEnd(28)} CL${String(r.cl).padStart(3)} HP${String(r.hpMax).padStart(3)} def${String(r.minDef).padStart(4)} atk${String(r.atk).padStart(3)} str${String(r.str).padStart(3)} ${r.aggr} ${r.lum?"LUM":""}`);
  }
}
console.log("\n=== Lumbridge-area NPCs CL>=5 sorted by CL ===");
for (const r of rows.filter(r=>r.lum && (r.cl??0)>=5).sort((a,b)=>(b.cl??0)-(a.cl??0))) {
  console.log(`${r.name.padEnd(28)} CL${String(r.cl).padStart(3)} HP${String(r.hpMax).padStart(3)} def${String(r.minDef).padStart(4)} atk${String(r.atk).padStart(3)} str${String(r.str).padStart(3)} ${r.aggr}`);
}

