import { readdirSync, readFileSync } from "fs";
import { join } from "path";

const dir = "wiki/npcs";
const PX = 3222, PZ = 3222;
const out: any[] = [];
for (const f of readdirSync(dir)) {
  if (!f.endsWith(".md")) continue;
  const t = readFileSync(join(dir, f), "utf8");
  const name = (t.match(/^# (.+)$/m) || [])[1] || f;
  const clm = (t.match(/\*\*Combat Level\*\* \| ([^\n|]+)/) || [])[1]?.trim() ?? "";
  const hpm = (t.match(/\*\*Hitpoints\*\* \| ([^\n|]+)/) || [])[1]?.trim() ?? "";
  const d = (t.match(/Stab Defence \| (-?\d+)/) || [])[1];
  const s = (t.match(/Slash Defence \| (-?\d+)/) || [])[1];
  const c = (t.match(/Crush Defence \| (-?\d+)/) || [])[1];
  const atk = (t.match(/Attack Bonus \| (-?\d+)/) || [])[1];
  const str = (t.match(/Strength Bonus \| (-?\d+)/) || [])[1];
  const nums = (x?: string) => x===undefined?[]:[Number(x)];
  const defVals = [...nums(d),...nums(s),...nums(c)];
  const minDef = defVals.length?Math.min(...defVals):NaN;
  const clVals = clm.match(/\d+/g)?.map(Number) ?? [];
  const hpVals = hpm.match(/\d+/g)?.map(Number) ?? [];
  if (!clVals.length || !hpVals.length) continue;
  const maxCL = Math.max(...clVals), maxHP = Math.max(...hpVals);
  if (maxCL < 8 || !(minDef <= 0)) continue;
  // nearest coordinate
  const coords = [...t.matchAll(/\((\d{4}), (\d{4})\)/g)].map(m=>[+m[1],+m[2]] as [number,number]);
  let best = Infinity, bc: [number,number]|null = null;
  for (const [x,z] of coords) {
    const dist = Math.hypot(x-PX, z-PZ);
    if (dist < best) { best = dist; bc=[x,z]; }
  }
  if (best > 220) continue;
  out.push({name, maxCL, maxHP, minDef, atk: atk===undefined?null:+atk, str: str===undefined?null:+str, best:Math.round(best), bc});
}
out.sort((a,b)=> a.best-b.best || b.maxCL-a.maxCL);
for (const r of out) console.log(`${r.name.padEnd(26)} CL${String(r.maxCL).padStart(3)} HP${String(r.maxHP).padStart(3)} def${String(r.minDef).padStart(4)} atk${String(r.atk).padStart(4)} str${String(r.str).padStart(4)} dist${String(r.best).padStart(4)} @${r.bc}`);

